#===============================================================================
# ProceduralEncounters - Settings
# Writes the wild encounters of a world generated by MapProceduralGenerator
# into PBS/encounters.txt: which Pokémon of the roster appear where, at which
# levels and how often, the same for a given world seed.
#===============================================================================
module ProceduralEncounters
  # The Pokémon of the game (types, Monotype types, generation, strength
  # tier, family): every species of Essentials that passes the roster rules.
  ROSTER_FILE = "docs/roster/pokedex.csv"
  # Evolutions (method and level) are read from these.
  POKEMON_PBS = "PBS/pokemon.txt"
  POKEMON_FORMS_PBS = "PBS/pokemon_forms.txt"
  ENCOUNTERS_PBS = "PBS/encounters.txt"

  # Tiles that trigger encounters in the Outside tileset (as stored by MapGen:
  # 384 + n for T<n>, 48 * slot for an autotile): tall grass T6, the same on
  # sand, dirt, gravel, mountain rock and meadow (T124, T125, T133, T147, T148,
  # T143) and very tall grass T7, water A1 (deep water included).
  GRASS_TILES = [6, 7, 124, 125, 133, 143, 147, 148].map { |n| 384 + n }.freeze
  WATER_TILES = [48].freeze

  # Ambiance of a route (MapProc, [Ambiance] of route.txt) => land biome,
  # « herbe » otherwise.
  AMBIANCE_BIOMES = { "prairie" => "prairie", "sable" => "sable", "terre battue" => "terre",
                      "minérale" => "minéral", "automne" => "automne", "forêt tropicale" => "tropical" }.freeze

  # Biome => type => weight (0 or absent = never there). A Pokémon takes the
  # best weight among its own types.
  BIOMES = {
    "herbe"    => { NORMAL: 3, BUG: 3, GRASS: 3, FLYING: 3, POISON: 2, ELECTRIC: 2, FAIRY: 2,
                    GROUND: 1, FIGHTING: 1, DARK: 1, PSYCHIC: 1, FIRE: 1, DRAGON: 1 },
    "prairie"  => { NORMAL: 3, GRASS: 3, FAIRY: 3, BUG: 2, FLYING: 2, ELECTRIC: 2, FIRE: 2,
                    PSYCHIC: 1, GROUND: 1, DRAGON: 1 },
    "sable"    => { GROUND: 3, FIRE: 3, ROCK: 2, BUG: 2, POISON: 1, NORMAL: 1, FIGHTING: 1,
                    DRAGON: 1, STEEL: 1 },
    "terre"    => { FIGHTING: 3, GROUND: 2, ROCK: 2, NORMAL: 2, DARK: 2, FIRE: 2, STEEL: 1,
                    POISON: 1 },
    "foret"    => { BUG: 3, GRASS: 3, GHOST: 2, FAIRY: 2, POISON: 2, DARK: 2, PSYCHIC: 1,
                    NORMAL: 1, FLYING: 1 },
    "minéral"  => { ROCK: 3, STEEL: 3, GROUND: 2, FIGHTING: 2, ELECTRIC: 1, ICE: 1, DRAGON: 1,
                    NORMAL: 1 },
    "automne"  => { GRASS: 3, BUG: 3, GHOST: 2, DARK: 2, NORMAL: 2, FLYING: 2, FIRE: 1,
                    POISON: 1, PSYCHIC: 1 },
    "tropical" => { GRASS: 3, BUG: 3, POISON: 3, DRAGON: 2, FLYING: 2, FAIRY: 1, ELECTRIC: 1,
                    FIGHTING: 1, NORMAL: 1 },
    "montagne" => { ROCK: 3, GROUND: 3, FIGHTING: 3, FLYING: 2, STEEL: 2, DRAGON: 2, ICE: 2,
                    FIRE: 1, NORMAL: 1 },
    "ville"    => { NORMAL: 3, POISON: 2, ELECTRIC: 2, STEEL: 2, PSYCHIC: 2, DARK: 2, FAIRY: 2,
                    GHOST: 1, FIGHTING: 1, FIRE: 1, GRASS: 1 },
    "grotte"   => { ROCK: 3, GROUND: 3, STEEL: 2, GHOST: 2, DARK: 2, POISON: 2, DRAGON: 2,
                    ICE: 1, FIGHTING: 1, PSYCHIC: 1 },
    "eau"      => { WATER: 3 }
  }.freeze
  # Excess of a place (« Demesure ») => land biome, over the ground's.
  EXCESS_BIOMES = { "forêt profonde" => "foret", "mer d'herbes" => "prairie", "chaos rocheux" => "montagne",
                    "montagne colossale" => "montagne", "ville-jardin" => "foret" }.freeze

  # Encounter types written: number of species drawn (range); max: at most
  # in the table, and overflow: at most as a last resort, when a type or a
  # family finds no room anywhere else; density (nil = none, as for the
  # rods); level shift from the place's levels; required type; coverage (a
  # Monotype run counts on it: land, caves, and surfing once Surf is
  # obtained); dominant: the table draws dominant types from its biome.
  TABLES = {
    "Land"     => { species: 4..7, max: 8, overflow: 14, density: 21, shift: 0, cover: true, dominant: true },
    "Cave"     => { species: 4..6, max: 7, overflow: 12, density: 5, shift: 1, cover: true, dominant: true },
    "Water"    => { species: 2..4, max: 5, overflow: 8, density: 2, shift: 0, type: :WATER, cover: :surf },
    "OldRod"   => { species: 1..2, max: 2, shift: -6, type: :WATER, weak: true },
    "GoodRod"  => { species: 2..3, max: 3, shift: -3, type: :WATER },
    "SuperRod" => { species: 2..4, max: 4, shift: 2, type: :WATER }
  }.freeze

  # Identity of a place: each land or cave table draws DOMINANT_TYPES types
  # from its biome's weights; Pokémon of those types make DOMINANT_SHARE of
  # its encounters. A type dominant in the previous place is DOMINANT_REPEAT
  # times as likely, so that two neighbours differ.
  DOMINANT_TYPES = 2
  DOMINANT_SHARE = 0.6
  DOMINANT_REPEAT = 0.25

  # A type counts as catchable in a tronçon (same number of seals) when it is
  # in that tronçon or in the COVER_WINDOW - 1 before it (the player can go
  # back). A Pokémon added for coverage gets at least COVER_PERCENT %.
  COVER_WINDOW = 2
  COVER_PERCENT = 5

  # Wild levels. Cap of n seals = LevelCap's cap (the level of the next
  # lieutenant), else CAPS[n]. Places between two lieutenants climb from the
  # previous cap to LEVEL_REACH of the gap up to the next one; the first ones
  # start at START_LEVEL.
  START_LEVEL = 3
  CAPS = [16, 24, 27, 33, 41, 49, 54, 57, 72].freeze
  LEVEL_REACH = 0.8

  # A Pokémon that evolves by level shows up from that level on. One that
  # evolves another way (stone, friendship, trade...) shows up from that many
  # seals, by stage (2 = first evolution, 3 = second).
  STAGE_SEALS = { 2 => 3, 3 => 6 }.freeze

  # Pokémon of a world: whole families drawn from the roster until about
  # WORLD_SPECIES of them, with at least TYPE_FAMILIES families a Monotype run
  # of each type can catch. The whole roster when it is that small. Each
  # further family is the most balancing one (types, tiers, generations)
  # among WORLD_SAMPLE drawn by chance: more keeps the world more even, less
  # makes worlds differ more.
  WORLD_SPECIES = 300
  TYPE_FAMILIES = 4
  WORLD_SAMPLE = 6

  # How often a Pokémon is drawn, by tier (« force » in the roster); « fort »
  # gains FORT_PER_SEAL per seal. Evolved stages are divided by their stage.
  TIER_WEIGHTS = { "faible" => 3.0, "moyen" => 2.0, "fort" => 0.5 }.freeze
  FORT_PER_SEAL = 0.25
  # Each table that already has a Pokémon makes it that much less likely
  # elsewhere, so that the whole roster shows up.
  REUSE_PENALTY = 0.7
end
